// newTestHub creates a Hub wired to a fake snapshotFn and the provided event
// channel. No GPU discovery runs (discoverGPUs returns empty on most hosts).
func newTestHub(t *testing.T, events chan ServerEvent, backends []BackendStatus) *Hub {
	t.Helper()
	h := NewHub(slog.Default(), events, func() []BackendStatus { return backends })
	h.gpus = nil // disable GPU polling in unit tests
	return h
}

func TestHub_Subscribe_getsSnapshot(t *testing.T) {
	events := make(chan ServerEvent, 8)
	h := newTestHub(t, events, nil)
	h.Start()
	defer h.Stop()

	ch, unsub := h.Subscribe()
	defer unsub()

	select {
	case msg := <-ch:
		if msg.Kind != MsgSnapshot {
			t.Errorf("first message kind: got %v, want MsgSnapshot", msg.Kind)
		}
		if msg.Snap == nil {
			t.Error("Snap must not be nil")
		}
	case <-time.After(time.Second):
		t.Fatal("timeout waiting for snapshot")
	}
}

func TestHub_EventRelay(t *testing.T) {
	events := make(chan ServerEvent, 8)
	h := newTestHub(t, events, nil)
	h.Start()
	defer h.Stop()

	ch, unsub := h.Subscribe()
	defer unsub()

	// Drain the snapshot.
	<-ch

	ev := ServerEvent{Kind: EventRaw, Backend: "local", Message: "hello"}
	events <- ev

	select {
	case msg := <-ch:
		if msg.Kind != MsgServerEvent {
			t.Errorf("kind: got %v, want MsgServerEvent", msg.Kind)
		}
		if msg.Event == nil || msg.Event.Message != "hello" {
			t.Errorf("Event: %+v", msg.Event)
		}
	case <-time.After(time.Second):
		t.Fatal("timeout waiting for server event")
	}
}

func TestHub_FanOut(t *testing.T) {
	events := make(chan ServerEvent, 8)
	h := newTestHub(t, events, nil)
	h.Start()
	defer h.Stop()

	ch1, unsub1 := h.Subscribe()
	ch2, unsub2 := h.Subscribe()
	defer unsub1()
	defer unsub2()

	<-ch1
	<-ch2

	events <- ServerEvent{Kind: EventRaw, Message: "broadcast"}

	for _, ch := range []<-chan HubMessage{ch1, ch2} {
		select {
		case msg := <-ch:
			if msg.Kind != MsgServerEvent {
				t.Errorf("kind: got %v, want MsgServerEvent", msg.Kind)
			}
		case <-time.After(time.Second):
			t.Fatal("timeout waiting for broadcast")
		}
	}
}

func TestHub_Unsubscribe(t *testing.T) {
	events := make(chan ServerEvent, 8)
	h := newTestHub(t, events, nil)
	h.Start()
	defer h.Stop()

	ch, unsub := h.Subscribe()
	<-ch // drain snapshot

	unsub()

	// Events sent after unsubscribe must not appear on ch.
	events <- ServerEvent{Kind: EventRaw, Message: "after-unsub"}

	select {
	case msg := <-ch:
		t.Errorf("received unexpected message after unsubscribe: %+v", msg)
	case <-time.After(100 * time.Millisecond):
		// expected
	}
}

func TestHub_Stop_closesChannels(t *testing.T) {
	events := make(chan ServerEvent, 8)
	h := newTestHub(t, events, nil)
	h.Start()

	ch, _ := h.Subscribe()
	<-ch // drain snapshot

	h.Stop()

	// Channel must be closed after Stop.
	select {
	case _, ok := <-ch:
		if ok {
			t.Error("expected channel to be closed, got value")
		}
	case <-time.After(time.Second):
		t.Fatal("channel not closed after Stop")
	}
}

func TestHub_Snapshot(t *testing.T) {
	events := make(chan ServerEvent, 8)
	h := newTestHub(t, events, nil)

	snap := h.Snapshot()
	if snap.Backends == nil {
		t.Error("Backends must not be nil")
	}
	if snap.GPUs == nil {
		t.Error("GPUs must not be nil")
	}
}

func TestHub_PollMetrics(t *testing.T) {
	slots, _ := json.Marshal([]slotJSON{{ID: 0, IsProcessing: false}})
	metrics := `# TYPE llamacpp:requests_processing gauge
llamacpp:requests_processing 1
# TYPE llamacpp:predicted_tokens_seconds gauge
llamacpp:predicted_tokens_seconds 42.5
`
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case "/metrics":
			w.Write([]byte(metrics)) //nolint:errcheck
		case "/slots":
			w.Write(slots) //nolint:errcheck
		default:
			http.NotFound(w, r)
		}
	}))
	defer srv.Close()

	// Extract port from test server URL.
	var port int
	fmt.Sscanf(srv.URL, "http://127.0.0.1:%d", &port)

	backends := []BackendStatus{{Name: "local", Port: port, Healthy: true}}
	events := make(chan ServerEvent, 8)
	h := newTestHub(t, events, backends)
	h.Start()
	defer h.Stop()

	ch, unsub := h.Subscribe()
	defer unsub()
	<-ch // snapshot

	// Wait for a MsgMetricsTick.
	deadline := time.After(3 * time.Second)
	for {
		select {
		case msg := <-ch:
			if msg.Kind == MsgMetricsTick {
				if msg.Metrics == nil {
					t.Fatal("Metrics is nil")
				}
				if msg.Metrics.RequestsProcessing != 1 {
					t.Errorf("RequestsProcessing: got %d, want 1", msg.Metrics.RequestsProcessing)
				}
				if len(msg.Metrics.Slots) != 1 {
					t.Errorf("Slots: got %d, want 1", len(msg.Metrics.Slots))
				}
				return
			}
		case <-deadline:
			t.Fatal("timeout waiting for MsgMetricsTick")
		}
	}
}

package monitor

import (
	"bufio"
	"encoding/json"
	"strconv"
	"strings"
)

// ParsePrometheusGauges parses gauge values from Prometheus text format.
// Only scalar gauge lines are extracted; labels are stripped from metric names.
// Returns map[metric_name]float64.
func ParsePrometheusGauges(text string) map[string]float64 {
	result := make(map[string]float64)
	scanner := bufio.NewScanner(strings.NewReader(text))
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		// Format: metric_name[{labels}] value [timestamp]
		fields := strings.Fields(line)
		if len(fields) < 2 {
			continue
		}
		name := fields[0]
		if i := strings.IndexByte(name, '{'); i >= 0 {
			name = name[:i]
		}
		val, err := strconv.ParseFloat(fields[1], 64)
		if err != nil {
			continue
		}
		result[name] = val
	}
	return result
}

// SlotState is the run state of a llama-server slot.
type SlotState int

const (
	SlotIdle       SlotState = 0
	SlotProcessing SlotState = 1
)

// Slot is one element from the GET /slots JSON response.
type Slot struct {
	ID              int       `json:"-"`
	State           SlotState `json:"-"`
	NCtx            int       `json:"n_ctx"`
	NPredict        int       `json:"n_predict"`
	Prompt          string    `json:"prompt"`
	TokensPredicted int       `json:"-"`
	TokensEvaluated int       `json:"-"`
}

// slotJSON is the raw JSON shape from llama-server /slots.
// The format changed: state (int) → is_processing (bool),
// tokens_predicted/tokens_evaluated → next_token[].n_decoded.
type slotJSON struct {
	ID           int  `json:"id"`
	NCtx         int  `json:"n_ctx"`
	IsProcessing bool `json:"is_processing"`

	// New format: n_decoded lives inside next_token array.
	NextToken []struct {
		NDecoded int `json:"n_decoded"`
	} `json:"next_token"`
}

// ParseSlots decodes a /slots JSON response.
func ParseSlots(data []byte) ([]Slot, error) {
	var raw []slotJSON
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, err
	}
	slots := make([]Slot, len(raw))
	for i, r := range raw {
		state := SlotIdle
		if r.IsProcessing {
			state = SlotProcessing
		}
		decoded := 0
		if len(r.NextToken) > 0 {
			decoded = r.NextToken[0].NDecoded
		}
		slots[i] = Slot{
			ID:              r.ID,
			State:           state,
			NCtx:            r.NCtx,
			TokensPredicted: decoded,
		}
	}
	return slots, nil
}

