package monitor

import (
	"context"
	"io"
	"log/slog"
	"net/http"
	"sync"
	"sync/atomic"
	"time"
)

// HubMessageKind identifies the type of a HubMessage.
type HubMessageKind int

const (
	MsgSnapshot    HubMessageKind = iota // initial state snapshot for a new subscriber
	MsgMetricsTick                       // backend metrics polled from /metrics + /slots
	MsgGPUTick                           // GPU hardware metrics polled from sysfs
	MsgServerEvent                       // structured event relayed from eventParser
	MsgStateChange                       // backend health state changed
)

// BackendMetrics is the latest polled state for one managed backend.
type BackendMetrics struct {
	Name                  string
	KVCacheUsageRatio     float64
	RequestsProcessing    int
	RequestsPending       int
	TokensPerSecond       float64
	PromptTokensPerSecond float64
	TokensPredictedTotal  int64
	PromptTokensTotal     int64
	Slots                 []Slot
}

// HubSnapshot is the full current state, delivered to new subscribers.
type HubSnapshot struct {
	Backends []BackendMetrics
	GPUs     []GPUMetrics
}

// HubMessage is a tagged message sent to subscribers.
type HubMessage struct {
	Kind    HubMessageKind
	Snap    *HubSnapshot    // MsgSnapshot
	Metrics *BackendMetrics // MsgMetricsTick
	GPUs    []GPUMetrics    // MsgGPUTick
	Event   *ServerEvent    // MsgServerEvent
	Backend string          // MsgStateChange
	Healthy bool            // MsgStateChange
}

// Hub subscribes to the event channel from Manager, polls each backend's HTTP
// endpoints and GPU sysfs files every second, and fans out to subscribers.
type Hub struct {
	log        *slog.Logger
	events     <-chan ServerEvent
	snapshotFn func() []BackendStatus
	gpus       []GPUInfo

	mu      sync.RWMutex
	metrics map[string]*BackendMetrics
	gpuData []GPUMetrics

	subsMu sync.Mutex
	subs   map[uint64]chan HubMessage
	nextID atomic.Uint64

	ctx    context.Context
	cancel context.CancelFunc
	wg     sync.WaitGroup

	client *http.Client
}

// NewHub creates a Hub. snapshotFn is called on every poll tick to obtain
// current backend addresses (Manager.Snapshot satisfies this). Call Start to
// begin the event relay and poll loop.
func NewHub(log *slog.Logger, events <-chan ServerEvent, snapshotFn func() []BackendStatus) *Hub {
	ctx, cancel := context.WithCancel(context.Background())
	h := &Hub{
		log:        log,
		events:     events,
		snapshotFn: snapshotFn,
		metrics:    make(map[string]*BackendMetrics),
		subs:       make(map[uint64]chan HubMessage),
		ctx:        ctx,
		cancel:     cancel,
		client:     &http.Client{Timeout: 3 * time.Second},
	}
	h.gpus = DiscoverGPUs()
	return h
}

// Start launches the event relay and poll goroutines.
func (h *Hub) Start() {
	h.wg.Add(2)
	go h.relayEvents()
	go h.pollLoop()
}

// Stop cancels both goroutines, waits for them to exit, then closes all
// subscriber channels. No goroutines are leaked after Stop returns.
func (h *Hub) Stop() {
	h.cancel()
	h.wg.Wait()

	h.subsMu.Lock()
	for id, ch := range h.subs {
		close(ch)
		delete(h.subs, id)
	}
	h.subsMu.Unlock()
}

// Subscribe registers a subscriber. The returned channel (buffered 64) receives
// a MsgSnapshot immediately, then subsequent messages as they arrive. The
// returned func removes the subscriber; Stop closes the channel.
func (h *Hub) Subscribe() (<-chan HubMessage, func()) {
	ch := make(chan HubMessage, 64)
	id := h.nextID.Add(1)

	h.subsMu.Lock()
	h.subs[id] = ch
	h.subsMu.Unlock()

	snap := h.Snapshot()
	select {
	case ch <- HubMessage{Kind: MsgSnapshot, Snap: &snap}:
	default:
	}

	return ch, func() {
		h.subsMu.Lock()
		delete(h.subs, id)
		h.subsMu.Unlock()
	}
}

// Statuses returns the current runtime state of all managed backends by
// delegating to the snapshotFn provided at construction. Safe to call
// concurrently.
func (h *Hub) Statuses() []BackendStatus {
	return h.snapshotFn()
}

// Snapshot returns a copy of the current full state synchronously.
func (h *Hub) Snapshot() HubSnapshot {
	h.mu.RLock()
	defer h.mu.RUnlock()

	backends := make([]BackendMetrics, 0, len(h.metrics))
	for _, m := range h.metrics {
		cp := *m
		backends = append(backends, cp)
	}
	gpuCopy := make([]GPUMetrics, len(h.gpuData))
	copy(gpuCopy, h.gpuData)
	return HubSnapshot{Backends: backends, GPUs: gpuCopy}
}

func (h *Hub) relayEvents() {
	defer h.wg.Done()
	for {
		select {
		case <-h.ctx.Done():
			return
		case ev, ok := <-h.events:
			if !ok {
				return
			}
			ev2 := ev
			h.broadcast(HubMessage{Kind: MsgServerEvent, Event: &ev2})
		}
	}
}

func (h *Hub) pollLoop() {
	defer h.wg.Done()
	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-h.ctx.Done():
			return
		case <-ticker.C:
			h.poll()
		}
	}
}

func (h *Hub) poll() {
	for _, b := range h.snapshotFn() {
		if b.Port == 0 {
			continue
		}
		m := h.fetchBackend(b)
		h.mu.Lock()
		h.metrics[b.Name] = m
		h.mu.Unlock()
		h.broadcast(HubMessage{Kind: MsgMetricsTick, Metrics: m})
	}

	gpuMetrics := ReadGPUMetrics(h.gpus)
	h.mu.Lock()
	h.gpuData = gpuMetrics
	h.mu.Unlock()
	if len(gpuMetrics) > 0 {
		h.broadcast(HubMessage{Kind: MsgGPUTick, GPUs: gpuMetrics})
	}
}

func (h *Hub) fetchBackend(b BackendStatus) *BackendMetrics {
	m := &BackendMetrics{Name: b.Name}
	base := "http://localhost:" + itoa(b.Port)

	if data, err := h.fetch(base + "/metrics"); err == nil {
		g := ParsePrometheusGauges(string(data))
		m.RequestsProcessing = int(g["llamacpp:requests_processing"])
		m.RequestsPending = int(g["llamacpp:requests_deferred"])
		m.TokensPerSecond = g["llamacpp:predicted_tokens_seconds"]
		m.PromptTokensPerSecond = g["llamacpp:prompt_tokens_seconds"]
		m.TokensPredictedTotal = int64(g["llamacpp:tokens_predicted_total"])
		m.PromptTokensTotal = int64(g["llamacpp:prompt_tokens_total"])
	} else {
		h.log.Debug("metrics fetch failed", "backend", b.Name, "error", err)
	}

	if data, err := h.fetch(base + "/slots"); err == nil {
		if slots, err := ParseSlots(data); err == nil {
			m.Slots = slots
		}
	} else {
		h.log.Debug("slots fetch failed", "backend", b.Name, "error", err)
	}

	return m
}

func (h *Hub) fetch(url string) ([]byte, error) {
	req, err := http.NewRequestWithContext(h.ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, err
	}
	resp, err := h.client.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	return io.ReadAll(resp.Body)
}

func (h *Hub) broadcast(msg HubMessage) {
	h.subsMu.Lock()
	defer h.subsMu.Unlock()
	for _, ch := range h.subs {
		select {
		case ch <- msg:
		default:
			// Drop to slow consumer.
		}
	}
}

// itoa converts an int to its decimal string representation without importing
// the strconv package at the call site.
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	buf := make([]byte, 0, 10)
	for n > 0 {
		buf = append([]byte{byte('0' + n%10)}, buf...)
		n /= 10
	}
	if neg {
		buf = append([]byte{'-'}, buf...)
	}
	return string(buf)
}

package gateway

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"net/http"
	"net/http/httputil"
	"net/url"
	"time"

	"github.com/nogo/wire/internal/config"
	"github.com/nogo/wire/internal/monitor"
	"github.com/nogo/wire/internal/process"
)

// backendManager is the subset of process.Manager the Gateway depends on.
type backendManager interface {
	Healthy(name string) bool
	// LoadOrGet returns the backend address for the named model, loading it on
	// demand if not already running. The caller must call release() when the
	// proxied request completes to decrement the in-flight counter.
	LoadOrGet(ctx context.Context, modelName string, params config.ModelParams) (addr string, release func(), err error)
	// ListModels returns all known models in non-idle states.
	ListModels() []monitor.ModelInfo
}

// Gateway is an HTTP reverse-proxy that routes OpenAI-compatible requests to llama-server processes.
type Gateway struct {
	cfg      *config.Config
	mgr      backendManager
	log      *slog.Logger
	affinity *affinityTable
	server   *http.Server
}

// New creates a Gateway backed by the given process manager.
// hub may be nil; when non-nil, /monitor and /monitor/ws routes are registered.
func New(cfg *config.Config, mgr *process.Manager, hub *monitor.Hub, log *slog.Logger) *Gateway {
	return newGateway(cfg, mgr, hub, log)
}

func newGateway(cfg *config.Config, mgr backendManager, hub *monitor.Hub, log *slog.Logger) *Gateway {
	// Build affinity table from warmup models.
	modelSlots := make(map[string]int, len(cfg.Warmup))
	for _, name := range cfg.Warmup {
		if params, ok := cfg.MatchModel(name); ok {
			modelSlots[name] = params.Slots
		}
	}

	g := &Gateway{cfg: cfg, mgr: mgr, log: log, affinity: newAffinityTable(modelSlots)}

	mux := http.NewServeMux()
	mux.HandleFunc("POST /v1/chat/completions", g.handleRoute)
	mux.HandleFunc("POST /v1/completions", g.handleRoute)
	mux.HandleFunc("POST /v1/embeddings", g.handleRoute)
	mux.HandleFunc("POST /v1/rerank", g.handleRoute)
	mux.HandleFunc("GET /v1/models", g.handleModels)
	mux.HandleFunc("GET /health", g.handleHealth)

	if hub != nil {
		mux.HandleFunc("GET /monitor", monitor.HandlePage)
		mux.HandleFunc("GET /monitor/ws", monitor.HandleWS(hub))
	}

	g.server = &http.Server{Addr: cfg.Listen, Handler: mux}
	return g
}

// ListenAndServe starts the HTTP server and shuts it down when ctx is cancelled.
func (g *Gateway) ListenAndServe(ctx context.Context) error {
	errCh := make(chan error, 1)
	go func() {
		if err := g.server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			errCh <- err
		}
	}()
	select {
	case err := <-errCh:
		return err
	case <-ctx.Done():
		shutCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		return g.server.Shutdown(shutCtx)
	}
}

// handleRoute extracts the model field from the JSON body and proxies to the matching process.
// If the model is known but not loaded, it is started on demand; the HTTP connection
// is held open until the model becomes healthy.
func (g *Gateway) handleRoute(w http.ResponseWriter, r *http.Request) {
	// Tee the body so the decoder and the upstream both see it.
	var captured bytes.Buffer
	tee := io.TeeReader(r.Body, &captured)
	dec := json.NewDecoder(tee)

	var payload struct {
		Model string `json:"model"`
	}
	if err := dec.Decode(&payload); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request_error", "invalid JSON: "+err.Error(), "bad_request")
		return
	}
	if payload.Model == "" {
		writeError(w, http.StatusBadRequest, "invalid_request_error", "missing model field", "bad_request")
		return
	}

	// Reconstruct full body: captured bytes (read by decoder) + rest not yet read.
	r.Body = io.NopCloser(io.MultiReader(&captured, r.Body))

	params, ok := g.cfg.MatchModel(payload.Model)
	if !ok {
		writeError(w, http.StatusNotFound, "invalid_request_error", "unknown model: "+payload.Model, "model_not_found")
		return
	}

	// LoadOrGet blocks until the model is healthy (or fails). The load context is
	// detached from the caller's request context inside the manager, so a client
